function createEssayIntent(parameters) {
  const {labels, weights, intercept} = parameters;
  function ranked(message) {
    const features=Object.entries(extract(message)).filter(([name])=>Object.hasOwn(weights,name));
    const scores=intercept.map(n=>n/1000);
    const evidence=new Set(features.filter(([k])=>k.startsWith('w:')).map(([k])=>k.slice(2,6))).size;
    if (!features.some(([k])=>/^[cdge]:/.test(k)) && evidence<2) return {label:null,confidence:0};
    let squares=0;
    for(const [name,value] of features) {
      const row=weights[name], scaled=value*row[0]/100;
      squares+=scaled*scaled;
    }
    const norm=Math.sqrt(squares)||1;
    for(const [name,value] of features) {
      const row=weights[name], scaled=value*row[0]/100/norm;
      for(let i=0;i<labels.length;i++) scores[i]+=scaled*row[i+1]/100;
    }
    const order=scores.map((score,i)=>({score,i})).sort((a,b)=>b.score-a.score);
    const gap=Math.max(0,order[0].score-order[1].score);
    return {label:labels[order[0].i],confidence:gap/(gap+1)};
  }
  function classify(message) {
    const result=ranked(message);
    return {label:result.label!=='other' && result.confidence>=0.45 ? result.label:null, confidence:result.confidence};
  }
  return Object.freeze({classify});
}

